  SELECT @stock_id, 'BUY', 45.00, 'SMA(20) 173.73 is 11.48% above SMA(50) 155.84: the short-term trend is stronger than the long-term trend. (+20)\nRSI(14) is 63.7, within the neutral 30-70 range. (0)\nMACD (9.329) is above its signal line (8.800): momentum is turning or staying positive. (+15)\nThe price rose 14.37% over the last 20 sessions, beyond the +/-3.0% momentum threshold. (+10)\nThe latest volume is 0.90x its 20-session average: no unusual trading activity. (0)\nScore +45 out of a possible +/-65 (BUY at +25 or more, SELL at -25 or less).', '{"bars":265,"close":185.0,"sma20":173.73,"sma50":155.8356,"rsi14":63.6629,"macd":9.3285,"macdSignal":8.8001,"momentum20Pct":14.374,"volumeRatio":0.9039,"maxScore":65.0,"signals":[{"rule":"SMA_CROSSOVER","signal":1,"contribution":20.0},{"rule":"RSI","signal":0,"contribution":0.0},{"rule":"MACD","signal":1,"contribution":15.0},{"rule":"MOMENTUM","signal":1,"contribution":10.0},{"rule":"VOLUME","signal":0,"contribution":0.0}]}', 'SAMPLE', '2026-10-30 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM recommendations WHERE stock_id = @stock_id AND data_source = 'SAMPLE' AND data_timestamp = '2026-10-30 00:00:00');

-- NASDAQ:TSLA - 265 SAMPLE bars (synthetic)
