  SELECT @stock_id, 'HOLD', -15.00, 'SMA(20) 119.79 is 4.15% below SMA(50) 124.98: the short-term trend is weaker than the long-term trend. (-20)\nRSI(14) is 43.1, within the neutral 30-70 range. (0)\nMACD (-2.759) is above its signal line (-2.986): momentum is turning or staying positive. (+15)\nThe price fell 9.85% over the last 20 sessions, beyond the +/-3.0% momentum threshold. (-10)\nThe latest volume is 1.06x its 20-session average: no unusual trading activity. (0)\nOverall the available indicators are mixed or neutral, so the engine suggests HOLD.\nScore -15 out of a possible +/-65 (BUY at +25 or more, SELL at -25 or less).', '{"bars":265,"close":115.86,"sma20":119.7915,"sma50":124.9776,"rsi14":43.0875,"macd":-2.759,"macdSignal":-2.9859,"momentum20Pct":-9.8506,"volumeRatio":1.0569,"maxScore":65.0,"signals":[{"rule":"SMA_CROSSOVER","signal":-1,"contribution":-20.0},{"rule":"RSI","signal":0,"contribution":0.0},{"rule":"MACD","signal":1,"contribution":15.0},{"rule":"MOMENTUM","signal":-1,"contribution":-10.0},{"rule":"VOLUME","signal":0,"contribution":0.0}]}', 'SAMPLE', '2026-10-30 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM recommendations WHERE stock_id = @stock_id AND data_source = 'SAMPLE' AND data_timestamp = '2026-10-30 00:00:00');

-- Watchlists of the demo users
  SELECT u.id, s.id FROM users u JOIN stocks s ON
    (u.email = 'priya@stocksense.test' AND s.symbol IN ('INFY', 'TCS', 'AAPL', 'NVDA'))
    OR (u.email = 'arjun@stocksense.test' AND s.symbol IN ('RELIANCE', 'HDFCBANK', 'SBIN'))
    OR (u.email = 'emma@stocksense.test' AND s.symbol IN ('MSFT', 'GOOGL', 'TSLA', 'AMZN', 'ITC'));

-- Sync log: the sample dataset was loaded, no API was called
  SELECT 'DEMO', '*', 'DEMO', 'Sample dataset loaded from sample-data.sql (synthetic prices, no API call).' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM api_sync_logs WHERE provider = 'DEMO' AND symbol = '*');
  SELECT NULL, 'SAMPLE_DATA_LOADED', 'sample-data.sql executed' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM activity_logs WHERE action = 'SAMPLE_DATA_LOADED');
