INSERT IGNORE INTO recommendation_rules (rule_key, name, description, weight, param_low, param_high) VALUES
  ('SMA_CROSSOVER', 'SMA crossover', 'SMA(20) above SMA(50) by more than param_low % is bullish (+weight), below by more than param_low % is bearish (-weight).', 20, 0.5, NULL),
  ('RSI', 'RSI zones', 'RSI(14) below param_low (oversold) adds +weight, above param_high (overbought) adds -weight.', 15, 30, 70),
  ('MACD', 'MACD vs signal', 'MACD(12,26) above its 9-period signal line adds +weight, below adds -weight.', 15, NULL, NULL),
  ('MOMENTUM', '20-session momentum', 'Price change over 20 sessions above +param_low % adds +weight, below -param_low % adds -weight.', 10, 3, NULL),
  ('VOLUME', 'Volume confirmation', 'Latest volume at least param_low x its 20-session average confirms the momentum direction (+/-weight).', 5, 1.2, NULL),
  ('DECISION', 'Decision thresholds', 'Score >= param_high is BUY, score <= param_low is SELL, anything between is HOLD. Weight is unused.', 0, -25, 25);
